test_anom_diff_ctor_local()
{
  int cdim = 2;
  struct gkyl_basis basis, cbasis;
  struct gkyl_range confRange, confRange_ext;
  make_ranges(cdim, &confRange, &confRange_ext, &basis, &cbasis);

  // "ELSE" branch (local boundary kernels) using copy BCs.
