  TEST_CHECK( diffusion->conf_range.volume == 64 );  // 8x8 interior cells
  TEST_CHECK( diffusion->surf != NULL );
  TEST_CHECK( diffusion->boundary_surf[0] != NULL );
  TEST_CHECK( diffusion->boundary_surf[1] != NULL );

  gkyl_dg_eqn_release(eqn);
