  { "prim_3x2v_p1", test_prim_3x2v_p1 },
  { "prim_1x1v_p2", test_prim_1x1v_p2 },
  { "prim_2x2v_p2", test_prim_2x2v_p2 },
  { "prim_acquire", test_prim_acquire },
  { NULL, NULL },
};

